// ABOUTME: AiScanner main component - collapsible right sidebar for AI scanning feature
// ABOUTME: Orchestrates sub-components and manages state through hooks

import React, { useEffect } from "react";
import { useAiScannerState } from "./hooks";
import { AiScannerHeader } from "./AiScannerHeader";
import { AiScannerContent } from "./AiScannerContent";
import { CollapsedButton } from "./CollapsedButton";

/**
 * AiScanner - Right sidebar component with collapse functionality
 * 
 * Features:
 * - Fixed right sidebar (450px width, full height)
 * - Collapse to small button on the right edge
 * - X button to close completely
 * - >> button to collapse/expand
 * 
 * @example
 * ```ts
 * // From background script:
 * injectComponent({
 *   tabId: tab.id,
 *   componentName: 'AiScanner',
 *   props: {
 *     initialCollapsed: false,
 *     initialPageDOM: pageDOM,
 *     pageUrl: tab.url,
 *     tabId: tab.id,
 *   },
 * });
 * ```
 */
export const AiScanner: React.FC<any> = ({
    onClose,
    initialCollapsed = false,
    initialPageDOM,
    pageUrl,
    tabId,
}) => {
    // State management via custom hook
    const {
        isCollapsed,
        toggleCollapse,
        scanText,
        scanStatus,
        scanError,
        threatLevel,
        retryScan,
    } = useAiScannerState(initialCollapsed, initialPageDOM, pageUrl);

    // Handle close
    const handleClose = () => {
        if (onClose) {
            onClose();
        }
    };

    // Collapsed state - small button on right edge
    if (isCollapsed) {
        return <CollapsedButton onClick={toggleCollapse} />;
    }

    // Expanded state - full sidebar
    return (
        <div
            data-testid="ai-scanner-expanded"
            className="
                fixed top-0 right-0 bottom-0
                w-[450px] h-full
                bg-backdrop
                shadow-2xl
                border-l border-tragic-200
                z-2147483646
                flex flex-col
                font-roboto
            "
        >
            <AiScannerHeader 
                onCollapse={toggleCollapse}
                onClose={handleClose}
            />
            
            <AiScannerContent
                scanText={scanText}
                scanStatus={scanStatus}
                scanError={scanError}
                threatLevel={threatLevel}
                pageUrl={pageUrl}
                onRetry={retryScan}
            />
            
        </div>
    );
};
