// ABOUTME: Reusable close button component for injectable components
// ABOUTME: Provides consistent styling and behavior for dismissing components

import React from "react";

export interface CloseButtonProps {
    /** Callback when clicked */
    onClose: () => void;
    /** Optional additional CSS classes */
    className?: string;
    /** Show label text (default: false) */
    showLabel?: boolean;
    /** Custom label text (default: "Close") */
    label?: string;
}

/**
 * Close button component with consistent styling
 * 
 * @example
 * ```tsx
 * <CloseButton onClose={() => console.log('Closed!')} />
 * <CloseButton onClose={handleClose} showLabel label="Dismiss" />
 * ```
 */
export const CloseButton: React.FC<CloseButtonProps> = ({
    onClose,
    className = "",
    showLabel = false,
    label = "Close",
}) => {
    return (
        <button data-testid="button-a380c060" 
            onClick={onClose}
            className={`
                inline-flex items-center justify-center
                text-tragic hover:text-primary
                transition-colors duration-200
                focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2
                ${className}
            `.trim()}
            aria-label={label}
            type="button"
        >
            {/* X icon */}
            <svg data-testid="svg-8fc7ea12" 
                className="w-5 h-5"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
                xmlns="http://www.w3.org/2000/svg"
            >
                <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M6 18L18 6M6 6l12 12"
                />
            </svg>
            {showLabel && <span data-testid="span-5ea756d4"  className="ml-2">{label}</span>}
        </button>
    );
};
