// ABOUTME: Component registry that maps component names to React components
// ABOUTME: Import and register all injectable components here

import React from "react";
import { ExampleNotification } from "./ExampleNotification";
import { AiScanner } from "./AiScanner";

/**
 * Component map - add new injectable components here
 * 
 * The key is the component name used when calling injectComponent()
 * The value is the React component to render
 */
export const INJECTABLE_COMPONENTS: Record<string, React.ComponentType<any>> = {
    'ExampleNotification': ExampleNotification,
    'AiScanner': AiScanner,
    // Add more components here as needed
};

/**
 * Get a component by name
 * @param name - Component name
 * @returns React component or undefined if not found
 */
export function getInjectableComponent(name: string): React.ComponentType<any> | undefined {
    return INJECTABLE_COMPONENTS[name];
}

/**
 * Check if a component is registered
 * @param name - Component name
 * @returns true if component is registered
 */
export function hasInjectableComponent(name: string): boolean {
    return name in INJECTABLE_COMPONENTS;
}

/**
 * Get list of all registered component names
 * @returns Array of component names
 */
export function getRegisteredComponentNames(): string[] {
    return Object.keys(INJECTABLE_COMPONENTS);
}
