// ABOUTME: Example notification component demonstrating the injectable component pattern
// ABOUTME: Shows how to use base utilities, props, auto-close, and styling with Tailwind

import React from "react";
import { NotificationProps } from "./types";
import { useAutoClose, CloseButton, PositionWrapper } from "./base";

/**
 * Example notification component
 * 
 * Demonstrates:
 * - Using NotificationProps interface
 * - Auto-close with useAutoClose hook
 * - CloseButton component
 * - PositionWrapper for layout
 * - Tailwind styling
 * - Type-based styling variants
 * 
 * @example
 * ```ts
 * // From background script:
 * injectComponent(tabId, 'ExampleNotification', {
 *   title: 'Success!',
 *   message: 'Your action was completed successfully.',
 *   type: 'success',
 *   autoDismiss: 5000,
 * });
 * ```
 */
export const ExampleNotification: React.FC<NotificationProps> = ({
    title,
    message,
    type = 'info',
    autoDismiss = 0,
    onClose,
}) => {
    // Auto-close after timeout if specified
    useAutoClose(onClose, autoDismiss);

    // Type-based styling using your custom theme colors from theme.css
    const typeStyles = {
        info: {
            icon: (
                <svg data-testid="svg-af9bd140"  className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
            ),
            // Using theme.css colors: --color-primary-100, --color-primary-400, --color-primary
            colors: 'bg-primary-100 border-primary-300 text-tragic',
            iconColor: 'text-primary',
        },
        success: {
            icon: (
                <svg data-testid="svg-631f16cd"  className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
            ),
            // Using theme.css colors: --color-success-100, --color-success-300, --color-success
            colors: 'bg-success-100 border-success-300 text-tragic',
            iconColor: 'text-success',
        },
        warning: {
            icon: (
                <svg data-testid="svg-fd6e7d73"  className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                </svg>
            ),
            // Using theme.css colors: --color-warning-100, --color-warning-300, --color-warning
            colors: 'bg-warning-100 border-warning-300 text-tragic',
            iconColor: 'text-warning',
        },
        error: {
            icon: (
                <svg data-testid="svg-2b5df465"  className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
            ),
            // Using theme.css colors: --color-danger-100, --color-danger-300, --color-danger
            colors: 'bg-danger-100 border-danger-300 text-tragic',
            iconColor: 'text-danger',
        },
    };

    const style = typeStyles[type];

    const handleClose = () => {
        console.log('[ExampleNotification] Closing notification');
        if (onClose) {
            onClose();
        }
    };

    return (
        <PositionWrapper 
            variant="card" 
            maxWidth="400px"
            className={`${style.colors} font-roboto`}
        >
            <div data-testid="div-ed9ea38d"  className="flex items-start space-x-3">
                {/* Icon */}
                <div data-testid="div-05564330"  className={`shrink-0 ${style.iconColor}`}>
                    {style.icon}
                </div>

                {/* Content - using your custom text styles from layer.css */}
                <div data-testid="div-4c22b3ef"  className="flex-1 min-w-0">
                    {title && (
                        <h3 data-testid="h3-66bfdfad"  className="text-base font-medium leading-6 tracking-[0.15px] text-tragic mb-1">
                            {title}
                        </h3>
                    )}
                    <p data-testid="p-7159d47d"  className="text-sm font-normal text-tragic-400 leading-5">
                        {message}
                    </p>
                    {autoDismiss > 0 && (
                        <p data-testid="p-44a7030a"  className="text-xs mt-2 text-tragic-300">
                            Auto-dismiss in {Math.round(autoDismiss / 1000)}s
                        </p>
                    )}
                </div>

                {/* Close button */}
                {onClose && (
                    <div data-testid="div-6516776a"  className="shrink-0">
                        <CloseButton 
                            onClose={handleClose}
                            className="p-1"
                        />
                    </div>
                )}
            </div>
        </PositionWrapper>
    );
};
