import { injectComponent } from "@/utils/inject-component-helper";
import { closePopupCurrentWindow } from "$Popup/utils/general";
import { chrome } from "@/utils/polyfill";
import { TARGET_BROWSER } from '@/app/scripts/browser-const';
import { BROWSER_NAME } from '@/app/scripts/app-consts.js';
import { telemetryMalware } from '@/utils/telemetry.js';

// Re-export from feature-flags.ts to maintain backward compatibility
export { shouldHideAiScannerFeature } from './feature-flags';

/**
 * Handles AI Scanner button click logic
 * Downloads model if needed, then shows the scanner when ready
 */
export const handleAiScannerButtonClick = async (
    isReadyToUse: boolean,
    needsDownload: boolean,
    isDownloading: boolean
) => {
    try {
        if (isReadyToUse) {
            await handleShowBGAiScanner();
        } else if (needsDownload) {
            const session = await LanguageModel.create();
            session.destroy();
            await handleShowBGAiScanner();
        } else if (isDownloading) {
            return; // Do nothing, just wait for the download to finish
        }
    } catch (err) {
        console.error("Error handling Ai Scanner button click:", err);
    }
};

/**
 * Handle showing the AI Scanner
 * This should only be called when the model is ready (availability === "available")
 * Model download is handled by the AiScannerPopupShieldBtn component
 */
export const handleShowBGAiScanner = async () => {
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    
    let availability = 'unavailable';
    try {
        const result = await chrome.runtime.sendMessage({ type: 'MSG_AI_MODEL_AVAILABILITY' });
        availability = result?.availability ?? 'unavailable';
    } catch (err) {
        console.warn('[AiScanner] Availability check failed:', err);
    }
    
    if (availability !== 'available') {
        console.warn('[AiScanner] Model not ready. Availability:', availability);
        return;
    }
        
    // Get DOM from the page
    const [result] = await chrome.scripting.executeScript({
        target: { tabId: tab.id as number },
        func: () => {
            // Get the whole DOM as HTML string
            return document.documentElement.outerHTML;
        },
    });
    
    const pageDOM = result.result;

    closePopupCurrentWindow();
    
    await injectComponent({
        tabId: tab.id as number,
        componentName: 'AiScanner',
        props: {
            initialCollapsed: false,
            initialPageDOM: pageDOM,  // Pass the DOM data
            pageUrl: tab.url,  // Pass the current URL
            tabId: tab.id,  // Pass tab ID for message passing
        },
    });
};

/**
 * Handles detection of DANGEROUS threat level
 * Called when AI Scanner detects a dangerous/malicious website
 * 
 * @param pageUrl - URL of the scanned page
 * 
 * @example
 * ```ts
 * handleDangerousThreatDetected(
 *   'https://phishing-site.com'
 * );
 * ```
 */
export const handleDangerousThreatDetected = async (
    pageUrl: string
): Promise<void> => {
    try {

        const subtype = TARGET_BROWSER as string === BROWSER_NAME.Chrome ? 'gemini_nano'
            : TARGET_BROWSER as string === BROWSER_NAME.Edge ? 'phi_mini'
            : 'other';
        // Send telemetry to DSE for Scam Guard Mini detection
        await telemetryMalware(
            'scam_guard_mini',                    // type
            subtype,                          // subtype
            pageUrl,                         // url - the detected malicious URL
            pageUrl,                         // tabURL - parent page (same as url in this case)
            [pageUrl],                       // tabHistory - navigation history
            'AI_Scam_Guard_Mini_Detection',  // threatName - descriptive name
            undefined                        // ruleId - not applicable for AI detection
        );
    } catch (err) {
        console.error('[AiScanner] Error sending telemetry for dangerous detection:', err);
    }
};