
import React from "react";
import ReactMarkdown from 'react-markdown';
import BGSvgIcon from "$Popup/components/core/BGSvgIcon";
import type { ThreatLevel, ScanStatus, ThreatStyleMap } from './types';
import BGTooltip from "$Popup/components/core/BGTooltip";
import { TARGET_BROWSER } from '@/app/scripts/browser-const'
import { BROWSER_NAME } from '@/app/scripts/app-consts.js'

const AnimatedDots: React.FC = () => {
    const [count, setCount] = React.useState(1);
    React.useEffect(() => {
        const id = setInterval(() => setCount(c => (c % 3) + 1), 500);
        return () => clearInterval(id);
    }, []);
    return <span data-testid="span-6ac1fa52" aria-hidden="true">{`.`.repeat(count)}</span>;
};

const getTooltipContent = () => {
    if (TARGET_BROWSER as string === BROWSER_NAME.Chrome) {
        return `Scam Guard Mini is powered by Google Gemini Nano and runs entirely in your browser.
            Your data stays on your device and we never see it.`;
    } else if (TARGET_BROWSER as string === BROWSER_NAME.Edge) {
        return `Scam Guard Mini is powered by Microsoft Phi Mini and runs entirely in your browser.
            Your data stays on your device and we never see it.`;
    }
}

interface AiScannerContentProps {
    scanText: string;
    scanStatus: ScanStatus;
    threatLevel: ThreatLevel;
    scanError: string;
    pageUrl?: string;
    onRetry?: () => void;
}

const THREAT_STYLES: ThreatStyleMap = {
    safe: { bg: 'bg-success-100', text: 'text-success', border: 'border-success-400', label: 'Safe' },
    neutral: { bg: 'bg-primary-100', text: 'text-primary', border: 'border-primary-300', label: 'No obvious threats' },
    warning: { bg: 'bg-warning-100', text: 'text-warning', border: 'border-warning-400', label: 'Suspicious' },
    danger: { bg: 'bg-danger-100', text: 'text-danger', border: 'border-danger-400', label: 'Dangerous' },
};

const OUR_RECOMMENDATION: Record<string, { header: string; desc: string }> = {
    safe: { header: 'Safe', desc: "We didn't find anything suspicious. You're good to continue." },
    neutral: { header: 'Nothing found', desc: "We didn't find anything suspicious, but stay alert when sharing personal info online." },
    warning: { header: 'Use caution', desc: 'This site has some signs of a scam site. Avoid entering any personal info or passwords here.' },
    danger: { header: "Don't trust", desc: 'This website shows multiple indicators consistent with a phishing scam.' },
};

export const AiScannerContent: React.FC<AiScannerContentProps> = ({
    scanText,
    scanStatus,
    threatLevel,
    scanError,
    pageUrl,
    onRetry,
}) => {
    const threat = threatLevel ? THREAT_STYLES[threatLevel] : null;
    const rec = threatLevel ? OUR_RECOMMENDATION[threatLevel] : null;

    let domain = '';
    if (pageUrl) {
        try { domain = new URL(pageUrl).hostname; } catch { domain = pageUrl; }
    }

    // Show loading card while scanning before threat level is detected
    const isLoading = (scanStatus === 'idle' || scanStatus === 'scanning') && !threatLevel;
    // Show result card as soon as threat level is known
    const showResult = !!threat && !!rec && scanStatus !== 'error';

    return (
        <div data-testid="div-130dad96" className="bg-tragic-100 flex flex-col flex-1 overflow-hidden p-6 gap-4">

            {/* Analyzing / loading card */}
            {isLoading && !showResult && (
                <>
                    <div data-testid="div-daef2b3b" className="flex items-center">
                        <BGSvgIcon iconName="ai-scanner-shield" width={22} />
                        <h4 data-testid="h4-af1ea60c" className="ml-2 text-tragic text-sm">Checking<AnimatedDots /></h4>
                    </div>
                    {/* Animated gradient border: spinning conic-gradient behind a 2px gap */}
                    <div data-testid="div-a2825fee" className="relative rounded-xl p-0.5 overflow-hidden">
                        <div data-testid="div-6e9d1778" className="absolute inset-[-150%] animate-[spin_2s_linear_infinite] bg-[conic-gradient(from_0deg,_#5a12cc,_#7c3aed,_#e1c1ff,_#7c3aed,_#571bb4,_#501daa,_#a74cff,_#5605e1,_#5c18c7)]" />
                        <div data-testid="div-analyzing" className="relative rounded-[10px] p-5 bg-backdrop">
                            <div data-testid="div-7c912f56" className="flex items-center justify-between mb-3">
                                <span data-testid="span-b4ebcae9" className="font-bold text-tragic text-lg">Analyzing<AnimatedDots /></span>
                                <div data-testid="div-4608d55b" className="w-6 h-6 border-4 border-tragic-200 border-t-primary border-solid rounded-full animate-spin" />
                            </div>
                            <div data-testid="div-e5092fd3" className="h-5 bg-tragic-200 rounded-sm animate-pulse w-full mb-2" />
                            <div data-testid="div-804328c2" className="h-5 bg-tragic-200 rounded-sm animate-pulse w-2/3" />
                        </div>
                    </div>
                </>
            )}

            {/* Result card */}
            {showResult && !isLoading && (
                <>
                    <div data-testid="div-ecb7c6ef" className="flex items-center gap-2">
                        <BGSvgIcon iconName="ai-scanner-shield" width={22} />
                        <h4 data-testid="h4-de614560" className="text-tragic text-sm">Scam Guard-mini</h4>
                        <BGTooltip
                            content={getTooltipContent()}
                            position="right"
                            bgColorClass="bg-tragic-400"
                            textColorClass="text-backdrop-200"
                            maxWidth="200px"
                            usePortal={true}
                        >
                            <div data-testid="div-c0bb52f5" className="cursor-pointer">
                                <BGSvgIcon
                                    iconName="info"
                                    size={14}
                                />
                            </div>
                        </BGTooltip>
                    </div>
                    <div data-testid="div-056ffd02" className={`border-2 border-solid ${threat!.border} rounded-xl p-5 bg-backdrop`}>
                        {/* Domain + badge row */}
                        <div data-testid="div-f7e8b7a5" className="flex items-center justify-between mb-3">
                            {domain && (
                                <span data-testid="span-b972db72" className="text-sm font-semibold text-tragic-400 truncate max-w-[60%]">{domain}</span>
                            )}
                            <span data-testid="span-9a080037" className={`text-xs font-semibold px-2.5 py-1 rounded-full ${threat!.bg} ${threat!.text}`}>
                                {threat!.label}
                            </span>
                        </div>
                        {/* Recommendation */}
                        <p data-testid="p-4791cc15" className="font-bold text-tragic text-base mb-1">
                            Our recommendation:{' '}
                            <span data-testid="span-2d268a31" className={threat!.text}>{rec!.header}</span>
                        </p>
                        <p data-testid="p-f16e17f2" className="text-sm text-tragic-400 leading-relaxed">{rec!.desc}</p>
                    </div>
                </>
            )}

            {scanStatus !== 'error' && (
                <p data-testid="p-9c3b1a1e" className="text-sm text-tragic-400">
                    Note: Scam Guard-mini uses automated analysis and does not guarantee accuracy.
                    Please verify information independently.
                </p>
            )}

            {/* Streaming analysis text */}
            {scanStatus !== 'error' && (
                <div data-testid="div-3ae3fb8c"
                    className="
                        [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none]
                        [scrollbar-width:none]
                        p-5 rounded-xl border-tragic-200 border-solid border
                        bg-backdrop flex-1 overflow-y-auto text-sm
                        text-tragic leading-relaxed
                        prose prose-sm max-w-none
                    ">
                    {!scanText ? (
                        <div data-testid="div-stream-skeleton" className="mt-3 space-y-2">
                            <h4 data-testid="h4-21a68f8c" className="font-semibold text-base mb-3">Result</h4>
                            <div data-testid="div-94e5cd71" className="h-5 bg-tragic-200 rounded-sm animate-pulse w-full" />
                            <div data-testid="div-21a68f8c" className="h-5 bg-tragic-200 rounded-sm animate-pulse w-8/12" />
                            <div data-testid="div-97637c56" className="h-5 bg-tragic-200 rounded-sm animate-pulse w-5/12" />
                            <div data-testid="div-94e5cd71" className="h-5 bg-tragic-200 rounded-sm animate-pulse w-full" />
                            <div data-testid="div-21a68f8c" className="h-5 bg-tragic-200 rounded-sm animate-pulse w-7/12" />
                            <div data-testid="div-97637c56" className="h-5 bg-tragic-200 rounded-sm animate-pulse w-2/3" />
                        </div>
                    ) : <ReactMarkdown
                        disallowedElements={['img', 'a', 'script', 'iframe', 'object', 'embed', 'link', 'style', 'form', 'input', 'button']}
                        unwrapDisallowed={true}
                        components={{
                            h2: ({ children }) => <p data-testid="p-50fc97b8" className="font-semibold text-base mb-3">{children}</p>,
                        }}
                    >{scanText}</ReactMarkdown>}
                </div>
            )}

            {/* Error card */}
            {scanStatus === 'error' && (
                <>
                    <div data-testid="div-0a808a15" className="flex items-center gap-2">
                        <BGSvgIcon iconName="ai-scanner-shield" width={22} />
                        <h4 data-testid="h4-f650dc0e" className="text-tragic text-sm">Scam Guard-mini</h4>
                        <BGTooltip
                            content={getTooltipContent()}
                            position="right"
                            bgColorClass="bg-tragic-400"
                            textColorClass="text-backdrop-200"
                            maxWidth="200px"
                            usePortal={true}
                        >
                            <div data-testid="div-7f2763ff" className="cursor-pointer">
                                <BGSvgIcon
                                    iconName="info"
                                    size={14}
                                    className="text-tragic-400"
                                />
                            </div>
                        </BGTooltip>
                    </div>
                    <div data-testid="div-4919deb9" className="flex flex-col items-center justify-center text-center py-8 px-6 rounded-xl border border-solid border-tragic-200 bg-backdrop">
                        <div data-testid="div-error-icon" className="mb-6">
                            <BGSvgIcon iconName="not-found" size={120} />
                        </div>
                        <h3 data-testid="h3-error-title" className="text-tragic text-lg font-medium mb-5">
                            Something went wrong
                        </h3>
                        <p data-testid="p-error-message" className="text-tragic-400 text-sm font-normal">
                            {scanError || 'Please check your connection and try again.'}
                        </p>
                        <p data-testid="p-error-support" className="text-tragic-400 text-sm font-normal mb-5">
                            Still not working?{' '}
                            <a data-testid="a-db015a43"
                                href="https://support.malwarebytes.com"
                                target="_blank"
                                rel="noopener noreferrer"
                                className="text-primary hover:text-primary-hover font-medium"
                            >
                                Contact support.
                            </a>
                        </p>
                        <button data-testid="button-228991e0"
                            onClick={() => onRetry?.()}
                            className="flex items-center bg-primary hover:bg-primary-hover h-fit rounded-4xl text-backdrop text-sm py-2 px-10 min-w-fit"
                        >
                            Try again
                        </button>
                    </div>
                </>
            )}
        </div>
    );
};
