// ABOUTME: Main entry point for the injectable component bundle
// ABOUTME: Exposes global API for injecting React components into web pages

import { getInjectableComponent, getRegisteredComponentNames } from "@/app/popup/src/components/InjectableComponents";
import { createRegisteredInjector, destroyInjector, destroyAllInjectors, ContainerConfig } from "@/utils/inject-component";

/**
 * Global API for injecting components
 * Called from background script via chrome.scripting.executeScript
 */
interface InjectBGComponentArgs {
    /** Component name (must be registered in INJECTABLE_COMPONENTS) */
    componentName: string;
    /** Props to pass to component */
    props?: Record<string, any>;
    /** Container configuration */
    config?: Partial<ContainerConfig>;
}

/**
 * Registry to track component IDs by component name
 * Prevents duplicate instances of the same component
 */
const componentNameRegistry = new Map<string, string>();

/**
 * Inject a React component into the page
 *
 * @param args - Component name and configuration
 * @returns Component ID for later reference/cleanup
 */
function injectBGComponent(args: InjectBGComponentArgs): string | null {
    const { componentName, props = {}, config = {} } = args;

    // Check if component already exists and destroy it
    const existingComponentId = componentNameRegistry.get(componentName);
    if (existingComponentId) {
        destroyInjector(existingComponentId);
        componentNameRegistry.delete(componentName);
    }

    // Validate component exists
    const Component = getInjectableComponent(componentName);
    if (!Component) {
        console.error(`[BG Injectable Bundle] Component not found: ${componentName}`);
        return null;
    }

    // Generate unique ID if not provided
    const componentId = config.id || `bg-injectable-${componentName}-${Date.now()}`;

    // Merge config with defaults
    const fullConfig: ContainerConfig = {
        id: componentId,
        position: config.position || 'top-right',
        zIndex: config.zIndex,
        shadowMode: config.shadowMode,
    };

    // Add onClose handler to props that removes the component
    const propsWithClose = {
        ...props,
        onClose: () => {
            console.log(`[BG Injectable Bundle] Component closed: ${componentId}`);
            if (props.onClose) {
                props.onClose();
            }
            destroyInjector(componentId);
        },
    };

    try {
        // Create and register injector
        createRegisteredInjector(Component, propsWithClose, fullConfig);

        // Track component by name to prevent duplicates
        componentNameRegistry.set(componentName, componentId);

        return componentId;
    } catch (error) {
        console.error(`[BG Injectable Bundle] Error injecting component:`, error);
        return null;
    }
}

/**
 * Destroy a specific injected component
 *
 * @param componentId - ID of component to destroy
 * @returns true if found and destroyed
 */
function destroyBGComponent(componentId: string): boolean {
    const destroyed = destroyInjector(componentId);
    // Clean up name registry
    if (destroyed) {
        for (const [name, id] of componentNameRegistry.entries()) {
            if (id === componentId) {
                componentNameRegistry.delete(name);
                break;
            }
        }
    }
    return destroyed;
}

/**
 * Destroy all injected components
 */
function destroyAllBGComponents(): void {
    destroyAllInjectors();
    componentNameRegistry.clear();
}

/**
 * Get list of available component names
 */
function getBGComponentNames(): string[] {
    return getRegisteredComponentNames();
}

// Expose API to window (accessible from ISOLATED world)
declare global {
    interface Window {
        injectBGComponent: typeof injectBGComponent;
        destroyBGComponent: typeof destroyBGComponent;
        destroyAllBGComponents: typeof destroyAllBGComponents;
        getBGComponentNames: typeof getBGComponentNames;
    }
}

window.injectBGComponent = injectBGComponent;
window.destroyBGComponent = destroyBGComponent;
window.destroyAllBGComponents = destroyAllBGComponents;
window.getBGComponentNames = getBGComponentNames;
