// ABOUTME: React hook for auto-dismissing components after a timeout
// ABOUTME: Useful for temporary notifications and alerts

import { useEffect } from "react";

/**
 * Auto-dismiss hook that calls onClose after a timeout
 * 
 * @param onClose - Callback to call when timeout expires
 * @param timeout - Timeout in milliseconds (0 = disabled)
 * 
 * @example
 * ```tsx
 * const MyNotification = ({ onClose }) => {
 *   useAutoClose(onClose, 5000); // Auto-close after 5 seconds
 *   return <div>This will auto-dismiss</div>;
 * };
 * ```
 */
export function useAutoClose(onClose: (() => void) | undefined, timeout: number): void {
    useEffect(() => {
        if (!onClose || timeout <= 0) {
            return;
        }

        const timer = setTimeout(() => {
            onClose();
        }, timeout);

        return () => {
            clearTimeout(timer);
        };
    }, [onClose, timeout]);
}
