// ABOUTME: Wrapper component for positioning and common layout patterns
// ABOUTME: Handles backdrop, centering, spacing, and card styling

import React, { ReactNode } from "react";

export interface PositionWrapperProps {
    /** Content to render */
    children: ReactNode;
    /** Show backdrop overlay (default: false) */
    showBackdrop?: boolean;
    /** Backdrop click handler (if provided, backdrop is clickable) */
    onBackdropClick?: () => void;
    /** Background color/styling (default: white card) */
    variant?: 'card' | 'transparent' | 'minimal';
    /** Maximum width (default: 'auto') */
    maxWidth?: string | number;
    /** Padding (default: varies by variant) */
    padding?: string;
    /** Additional CSS classes */
    className?: string;
}

/**
 * Position wrapper that handles common layout patterns for injectable components
 * 
 * @example
 * ```tsx
 * // Notification card
 * <PositionWrapper variant="card" maxWidth="400px">
 *   <h3 data-testid="h3-a159452d">Notification</h3>
 *   <p data-testid="p-bd5e7f2a">Your content here</p>
 * </PositionWrapper>
 * 
 * // Modal with backdrop
 * <PositionWrapper 
 *   showBackdrop 
 *   onBackdropClick={handleClose}
 *   variant="card"
 *   maxWidth="600px"
 * >
 *   <h2 data-testid="h2-142f991d">Modal Title</h2>
 *   <p data-testid="p-47075f3a">Modal content</p>
 * </PositionWrapper>
 * ```
 */
export const PositionWrapper: React.FC<PositionWrapperProps> = ({
    children,
    showBackdrop = false,
    onBackdropClick,
    variant = 'card',
    maxWidth = 'auto',
    padding,
    className = "",
}) => {
    // Default padding based on variant
    const defaultPadding = variant === 'card' ? 'p-6' : variant === 'minimal' ? 'p-4' : 'p-0';
    const paddingClass = padding || defaultPadding;

    // Variant styles
    const variantClasses = {
        card: 'bg-backdrop rounded-2xl shadow-xl border border-gray-300',
        minimal: 'bg-white rounded-lg shadow-md',
        transparent: 'bg-transparent',
    };

    const maxWidthStyle = typeof maxWidth === 'number' ? `${maxWidth}px` : maxWidth;

    return (
        <>
            {/* Backdrop */}
            {showBackdrop && (
                <div data-testid="div-afc62281" 
                    className="fixed top-0 left-0 right-0 bottom-0 w-full h-full z-999999 bg-[rgba(13,25,47,0.5)]"
                    onClick={onBackdropClick}
                    role={onBackdropClick ? "button" : undefined}
                    aria-label={onBackdropClick ? "Close" : undefined}
                />
            )}

            {/* Content */}
            <div data-testid="div-8a189ea2" 
                className={`
                    ${variantClasses[variant]}
                    ${paddingClass}
                    ${className}
                `.trim()}
                style={{ maxWidth: maxWidthStyle }}
            >
                {children}
            </div>
        </>
    );
};
