// ABOUTME: Core utility for injecting React components into web pages with shadow DOM isolation
// ABOUTME: Handles shadow DOM creation, CSS injection, icon bundling, and ReactDOM rendering with cleanup

import React from "react";
import ReactDOM from "react-dom/client";
import cssText from "@/app/popup/src/styles/css-exporter.js";
import bundledIcons, { type IconBundle } from "@/app/popup/src/assets/icons/icons-exporter";

// Make bundled icons available globally for BGSvgIcon to use
declare global {
    interface Window {
        __BG_BUNDLED_ICONS__?: IconBundle;
    }
}

// Set up bundled icons on window for injectable components
if (typeof window !== 'undefined') {
    window.__BG_BUNDLED_ICONS__ = bundledIcons;
}

/**
 * Position presets for common UI patterns
 */
export type PositionPreset =
    | 'top-left'
    | 'top-center'
    | 'top-right'
    | 'center'
    | 'bottom-left'
    | 'bottom-center'
    | 'bottom-right'
    | 'sidebar-left'
    | 'sidebar-right'
    | 'fullscreen';

/**
 * Configuration for shadow host container
 */
export interface ContainerConfig {
    /** Unique ID for the shadow host element */
    id: string;
    /** Position preset or custom style object */
    position?: PositionPreset | React.CSSProperties;
    /** Z-index for stacking order (default: 2147483647) */
    zIndex?: number;
    /** Shadow DOM mode (default: 'open') */
    shadowMode?: 'open' | 'closed';
}

/**
 * Return value from createComponentInjector
 */
export interface InjectorInstance {
    /** Remove the component from DOM and cleanup */
    destroy: () => void;
    /** Reference to shadow host element */
    shadowHost: HTMLElement;
    /** Reference to shadow root */
    shadowRoot: ShadowRoot;
}

/**
 * Maps position presets to CSS styles
 */
const POSITION_PRESETS: Record<PositionPreset, React.CSSProperties> = {
    'top-left': {
        position: 'fixed',
        top: '16px',
        left: '16px',
    },
    'top-center': {
        position: 'fixed',
        top: '16px',
        left: '50%',
        transform: 'translateX(-50%)',
    },
    'top-right': {
        position: 'fixed',
        top: '16px',
        right: '16px',
    },
    'center': {
        position: 'fixed',
        top: '50%',
        left: '50%',
        transform: 'translate(-50%, -50%)',
    },
    'bottom-left': {
        position: 'fixed',
        bottom: '16px',
        left: '16px',
    },
    'bottom-center': {
        position: 'fixed',
        bottom: '16px',
        left: '50%',
        transform: 'translateX(-50%)',
    },
    'bottom-right': {
        position: 'fixed',
        bottom: '16px',
        right: '16px',
    },
    'sidebar-left': {
        position: 'fixed',
        top: '0',
        left: '0',
        height: '100%',
        width: '450px',
    },
    'sidebar-right': {
        position: 'fixed',
        top: '0',
        right: '0',
        height: '100%',
        width: '450px',
    },
    'fullscreen': {
        position: 'fixed',
        top: '0',
        left: '0',
        width: '100%',
        height: '100%',
    },
};

/**
 * Creates and injects a React component into a web page with shadow DOM isolation
 *
 * @param component - React component to render
 * @param props - Props to pass to the component
 * @param config - Container configuration
 * @returns Injector instance with destroy method
 *
 * @example
 * ```ts
 * const injector = createComponentInjector(
 *   MyNotification,
 *   { message: 'Hello!' },
 *   { id: 'my-notification', position: 'top-right' }
 * );
 *
 * // Later, to remove:
 * injector.destroy();
 * ```
 */
export function createComponentInjector<P = any>(
    component: React.ComponentType<P>,
    props: P,
    config: ContainerConfig
): InjectorInstance {
    const { id, position = 'top-right', zIndex = 2147483647, shadowMode = 'open' } = config;

    // Create shadow host element
    const shadowHost = document.createElement("div");
    shadowHost.id = id;

    // Apply positioning styles to shadow host
    const positionStyles: React.CSSProperties = typeof position === 'string'
        ? POSITION_PRESETS[position]
        : position;

    Object.assign(shadowHost.style, {
        ...positionStyles,
        zIndex: String(zIndex),
    });

    // Attach shadow DOM
    document.documentElement.appendChild(shadowHost);
    const shadowRoot = shadowHost.attachShadow({ mode: shadowMode });

    // Inject CSS into shadow DOM
    try {
        const styleSheet = document.createElement("style");
        styleSheet.textContent = cssText;
        shadowRoot.appendChild(styleSheet);
    } catch (error) {
        console.error(`[BG Injector] Error injecting CSS:`, error);
        // Continue without CSS - component may still be functional
    }

    // Create React container
    const reactContainer = document.createElement("div");
    shadowRoot.appendChild(reactContainer);

    // Render React component
    const root = ReactDOM.createRoot(reactContainer);
    root.render(React.createElement(component as React.ComponentType<any>, props));

    // Return instance with cleanup
    return {
        destroy: () => {
            root.unmount();
            shadowHost.remove();
        },
        shadowHost,
        shadowRoot,
    };
}

/**
 * Global storage for injector instances (for programmatic cleanup)
 */
const injectorRegistry = new Map<string, InjectorInstance>();

/**
 * Creates an injector and registers it for later cleanup
 *
 * @param component - React component to render
 * @param props - Props to pass to the component
 * @param config - Container configuration
 * @returns Injector instance
 */
export function createRegisteredInjector<P = any>(
    component: React.ComponentType<P>,
    props: P,
    config: ContainerConfig
): InjectorInstance {
    // Destroy existing instance with same ID if present
    const existing = injectorRegistry.get(config.id);
    if (existing) {
        existing.destroy();
    }

    const injector = createComponentInjector(component, props, config);
    injectorRegistry.set(config.id, injector);

    return injector;
}

/**
 * Destroys a registered injector by ID
 *
 * @param id - ID of the injector to destroy
 * @returns true if found and destroyed, false otherwise
 */
export function destroyInjector(id: string): boolean {
    const injector = injectorRegistry.get(id);
    if (injector) {
        injector.destroy();
        injectorRegistry.delete(id);
        return true;
    }
    return false;
}

/**
 * Destroys all registered injectors
 */
export function destroyAllInjectors(): void {
    injectorRegistry.forEach((injector) => injector.destroy());
    injectorRegistry.clear();
}
