
import { useState, useCallback, useEffect, useRef } from "react";
import { chrome } from "@/utils/polyfill";
import type { ThreatLevel, ScanStatus, PageSignals, PageForm, AiScanStreamMessage } from './types';
import { handleDangerousThreatDetected } from './logic';

/**
 * Hook to check LanguageModel availability
 * Returns availability state and derived convenience booleans
 * Automatically polls when download is in progress to detect state changes
 */
export function useLanguageModelAvailability() {
    const [availability, setAvailability] = useState<string | null>(null);

    useEffect(() => {
        const checkAvailability = async () => {
            try {
                const result = await LanguageModel.availability({
                    expectedInputs: [{ type: "text", languages: ["en"] }]
                });
                setAvailability(result);
                console.log(`[useLanguageModelAvailability] Availability check result: ${result}`);
            } catch (err) {
                console.error("Error checking LanguageModel availability:", err);
                setAvailability("unavailable");
            }
        };
        
        // Initial check
        checkAvailability();
        
        // Poll every 1 second when model is downloadable or downloading
        // This detects when download starts/completes automatically
        const shouldPoll = availability === "downloadable" || availability === "downloading";
        
        if (shouldPoll) {
            const interval = setInterval(checkAvailability, 1000);
            return () => clearInterval(interval);
        }
    }, [availability]);

    return {
        availability,
        isReadyToUse: availability === "available",
        needsDownload: availability === "downloadable",
        isDownloading: availability === "downloading",
        isUnavailable: availability === "unavailable" || availability === null,
    };
}

// Extracts security signals from an HTML string using DOMParser
function extractSignalsFromHTML(html: string, url: string): PageSignals {
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');

    let domain = '';
    try {
        domain = new URL(url).hostname;
    } catch {
        domain = url;
    }

    const forms: PageForm[] = Array.from(doc.querySelectorAll('form')).map(form => ({
        action: form.getAttribute('action') || 'none',
        method: (form.getAttribute('method') || 'GET').toUpperCase(),
        fields: Array.from(form.querySelectorAll('input, select, textarea')).map(el => {
            const name = el.getAttribute('name') || el.getAttribute('id') || 'unnamed';
            const type = el.getAttribute('type') || el.tagName.toLowerCase();
            return `${type}:${name}`;
        }),
    }));

    const hasPasswordField = doc.querySelectorAll('input[type="password"]').length > 0;

    const allLinks = Array.from(doc.querySelectorAll('a[href]'));
    const externalLinks = allLinks
        .map(a => a.getAttribute('href'))
        .filter(href => {
            if (!href) return false;
            try { return new URL(href).hostname !== domain; } catch { return false; }
        }) as string[];

    const hiddenIframes = Array.from(doc.querySelectorAll('iframe')).filter(f => {
        const style = f.getAttribute('style') || '';
        return style.includes('display:none') || style.includes('display: none') ||
            style.includes('visibility:hidden') || f.getAttribute('width') === '0';
    }).length;

    const urgencyPatterns = [
        'urgent', 'immediately', 'act now', 'limited time', 'expires',
        'account suspended', 'account locked', 'verify your', 'confirm your identity',
        'won a prize', 'congratulations', 'you have won', 'call now',
        'warning', 'alert', 'virus detected', 'unauthorized access', 'security alert',
    ];
    const pageText = (doc.body?.textContent || '').toLowerCase();
    const urgencyWords = urgencyPatterns.filter(w => pageText.includes(w));

    const mismatchedDomains = allLinks
        .filter(a => {
            const linkText = a.textContent?.trim().toLowerCase() || '';
            const href = a.getAttribute('href') || '';
            try {
                const linkDomain = new URL(href).hostname;
                return (linkText.includes('.com') || linkText.includes('.org')) && !linkText.includes(linkDomain);
            } catch { return false; }
        })
        .map(a => `"${a.textContent?.trim().substring(0, 50)}" -> ${a.getAttribute('href')}`)
        .slice(0, 5);

    const externalScripts = Array.from(doc.querySelectorAll('script[src]'))
        .map(s => s.getAttribute('src'))
        .filter(src => {
            try { return src && new URL(src).hostname !== domain; } catch { return false; }
        }) as string[];

    const metaRedirects = doc.querySelectorAll('meta[http-equiv="refresh"]').length > 0;
    // Sample text content for model context (truncated to 5000 chars)
    const textSample = (doc.body?.textContent || '').substring(0, 5000).trim();
    const hasPayment = /payment|credit card|billing|checkout|pay now|debit card/i.test(textSample);
    const metaDescription = doc.querySelector('meta[name="description"]')?.getAttribute('content') || '';

    return {
        url,
        domain,
        protocol: url.startsWith('https') ? 'https:' : 'http:',
        title: doc.title || '',
        metaDescription,
        hasPayment,
        forms,
        hasPasswordField,
        totalLinks: allLinks.length,
        externalLinks,
        hiddenIframes,
        urgencyWords,
        mismatchedDomains,
        externalScripts,
        metaRedirects,
        textSample,
    };
}

function detectThreatLevel(text: string): ThreatLevel {
    const lower = text.toLowerCase();
    if (lower.includes('threat level: safe') || lower.includes('threat level:** safe') || lower.includes('safe**')) return 'safe';
    if (lower.includes('threat level: no_obvious_threats') || lower.includes('no_obvious_threats**')) return 'neutral';
    if (lower.includes('threat level: suspicious') || lower.includes('suspicious**')) return 'warning';
    if (lower.includes('threat level: dangerous') || lower.includes('dangerous**')) return 'danger';
    return null;
}

/**
 * Main hook for AiScanner state management — handles collapse and AI scan
 *
 * @param initialCollapsed - Initial collapsed state
 * @param pageDOM - Full page HTML string passed from logic.ts
 * @param pageUrl - URL of the page being scanned
 */
export function useAiScannerState(
    initialCollapsed: boolean = false,
    pageDOM?: string,
    pageUrl?: string,
) {
    const [isCollapsed, setIsCollapsed] = useState(initialCollapsed);
    const [scanText, setScanText] = useState('');
    const [scanStatus, setScanStatus] = useState<ScanStatus>('idle');
    const [scanError, setScanError] = useState('');
    const portRef = useRef<chrome.runtime.Port | null>(null);
    const pageDOMRef = useRef(pageDOM);
    const pageUrlRef = useRef(pageUrl);
    const dangerousHandledRef = useRef(false);

    const toggleCollapse = useCallback(() => {
        setIsCollapsed(prev => {
            const newState = !prev;
            return newState;
        });
    }, []);

    // Extracted scan logic for reuse
    const startScan = useCallback(() => {
        const currentPageDOM = pageDOMRef.current;
        const currentPageUrl = pageUrlRef.current;
        
        if (!currentPageDOM || !currentPageUrl) return;

        // Disconnect any existing port
        if (portRef.current) {
            portRef.current.disconnect();
            portRef.current = null;
        }

        // Reset state
        setScanText('');
        setScanError('');
        setScanStatus('scanning');
        dangerousHandledRef.current = false;

        const signals = extractSignalsFromHTML(currentPageDOM, currentPageUrl);
        const port = (chrome as any).runtime.connect({ name: 'MSG_AI_SCAN_STREAM' });
        portRef.current = port;

        port.postMessage({ action: 'MSG_AI_SCAN_START', signals });

        port.onMessage.addListener((msg: AiScanStreamMessage) => {
            if (msg.type === 'MSG_AI_SCAN_CHUNK') {
                setScanText(msg.text);
            }
            if (msg.type === 'MSG_AI_SCAN_DONE') {
                setScanText(msg.text);
                setScanStatus('done');
            }
            if (msg.type === 'MSG_AI_SCAN_ERROR') {
                console.error('[AiScanner] Scan error:', msg.message);
                setScanError(msg?.message);
                setScanStatus('error');
            }
        });

        port.onDisconnect.addListener(() => {
            if (portRef.current === port) portRef.current = null;
        });
    }, []);

    // Auto-start scan on mount when page data is available
    useEffect(() => {
        if (!pageDOM || !pageUrl) return;
        startScan();

        return () => {
            if (portRef.current) {
                portRef.current.disconnect();
                portRef.current = null;
            }
        };
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []); // Run once on mount — pageDOM/pageUrl are the initial props

    const threatLevel = detectThreatLevel(scanText);

    // Handle dangerous threat detection - only when scan is DONE
    useEffect(() => {
        if (
            scanStatus === 'done' &&
            threatLevel === 'danger' &&
            !dangerousHandledRef.current &&
            pageUrl
        ) {
            dangerousHandledRef.current = true;

            // Call the handler (async, no need to await)
            handleDangerousThreatDetected(pageUrl).catch(err => {
                console.error('[AiScanner] Error calling handleDangerousThreatDetected:', err);
            });
        }
    }, [scanStatus, threatLevel, pageUrl]);

    // Retry function for error recovery
    const retryScan = useCallback(() => {
        startScan();
    }, [startScan]);

    return {
        // Collapse state
        isCollapsed,
        toggleCollapse,

        // Scan state
        scanText,
        scanStatus,
        scanError,
        threatLevel,
        retryScan,
    };
}
